{{- /*
  Renders the "Daily Spark" card on the home page.
  Reads site.Data.daily_spark (written by .github/workflows/daily-spark.yml).
  If the data file is missing or empty, nothing is rendered.
  Language-aware: switches headline / tag / title / task via .Lang.
*/ -}}

{{- $spark := hugo.Data.daily_spark -}}
{{- if and $spark (isset $spark "date") (isset $spark "zh") (isset $spark "en") -}}
  {{- $langKey := "zh" -}}
  {{- if eq .Lang "en" -}}
    {{- $langKey = "en" -}}
  {{- end -}}
  {{- $headline := "今日小火花" -}}
  {{- if eq $langKey "en" -}}
    {{- $headline = "Daily Spark" -}}
  {{- end -}}
  {{- $tag := index $spark.tag $langKey -}}
  {{- $title := index (index $spark $langKey) "title" -}}
  {{- $task := index (index $spark $langKey) "task" -}}

  <section class="daily-spark" aria-label="{{ $headline }}">
    <header class="daily-spark__head">
      <span class="daily-spark__label">{{ $headline }}</span>
      <time class="daily-spark__date" datetime="{{ $spark.date }}">{{ $spark.date }}</time>
    </header>
    <div class="daily-spark__body">
      <span class="daily-spark__tag">{{ $tag }}</span>
      <p class="daily-spark__title">{{ $title }}</p>
      <p class="daily-spark__task">{{ $task }}</p>
