{{- /*
  Giscus comment thread for the daily spark check-in section.
  Identical wiring to layouts/_partials/comments.html (article-page comments)
  except:
    * data-mapping = "specific"  (each day is its own discussion topic)
    * data-term    = "spark-{{ .date }}" (one thread per calendar day)
  Receives dict(page, date). Uses $page := .page for .Lang.
*/ -}}

{{- $page := .page -}}
{{- $date := .date -}}
{{- if and $page.Site.Params.comments.giscus.repoid $page.Site.Params.comments.giscus.categoryid -}}
<script src="https://giscus.app/client.js"
        data-repo="{{ $page.Site.Params.comments.giscus.repo }}"
        data-repo-id="{{ $page.Site.Params.comments.giscus.repoid }}"
        data-category="{{ $page.Site.Params.comments.giscus.category }}"
        data-category-id="{{ $page.Site.Params.comments.giscus.categoryid }}"
        data-mapping="specific"
        data-term="spark-{{ $date }}"
        data-strict="0"
        data-reactions-enabled="{{ if $page.Site.Params.comments.giscus.reactionsenabled }}1{{ else }}0{{ end }}"
        data-emit-metadata="0"
        data-input-position="bottom"
        data-theme="light"
        data-lang="{{ cond (eq $page.Lang "en") "en" "zh-CN" }}"
        data-light-theme="{{ $page.Site.Params.comments.giscus.lighttheme }}"
        data-dark-theme="{{ $page.Site.Params.comments.giscus.darktheme }}"
        crossorigin="anonymous"
        async>
</script>

<script>
  function setSparkGiscusTheme() {
    const iframe = document.querySelector('iframe.giscus-frame');
    if (!iframe) return;
    const theme = document.documentElement.getAttribute('data-theme') === 'dark'
      ? '{{ $page.Site.Params.comments.giscus.darktheme }}'
      : '{{ $page.Site.Params.comments.giscus.lighttheme }}';
    iframe.contentWindow.postMessage(
      { giscus: { setConfig: { theme } } },
      'https://giscus.app'
    );
  }
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new MutationObserver(setSparkGiscusTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    setSparkGiscusTheme();
  });
</script>
{{- end -}}

{{- /*
  Site-level home page override.
  Layout:
    .home-layout
      .home-main
        .home-spark     (Daily Spark hero, with placeholder fallback)
        .spark-checkin  (Giscus per-day check-in thread)
      .home-side
        .home-side__card  (Recent Posts, top 5)
        .home-side__card  (social icons)
  Only affects the home page (Hugo resolves home kind → index.html first);
  /posts/, /about/, etc. continue to use themes/PaperMod/layouts/list.html.
*/ -}}

{{- define "main" -}}
{{- $spark := hugo.Data.daily_spark -}}
{{- $sparkOK := and $spark (isset $spark "date") (isset $spark "zh") (isset $spark "en") -}}
{{- $langKey := cond (eq .Lang "en") "en" "zh" -}}
{{- $headline := cond (eq $langKey "en") "Daily Spark" "今日小火花" -}}
{{- $checkinLabel := cond (eq $langKey "en") "Check in Today" "今日打卡" -}}
{{- $recentLabel := cond (eq $langKey "en") "Recent Posts" "最近文章" -}}

<div class="home-layout">
  <div class="home-main">
    {{- if $sparkOK -}}
      {{- $tag := index $spark.tag $langKey -}}
      {{- $title := index (index $spark $langKey) "title" -}}
      {{- $task := index (index $spark $langKey) "task" -}}

      <section class="home-spark" aria-label="{{ $headline }}">
        <header class="home-spark__head">
          <span class="home-spark__tag">{{ $tag }}</span>
          <time class="home-spark__date" datetime="{{ $spark.date }}">{{ $spark.date }}</time>
        </header>
        <h2 class="home-spark__title">{{ $headline }}</h2>
        <p class="home-spark__sub">{{ $title }}</p>
        <p class="home-spark__task">{{ $task }}</p>
      </section>
    {{- else -}}
      <section class="home-spark home-spark--empty" aria-label="{{ $headline }}">
        <h2 class="home-spark__title">{{ $headline }}</h2>
        <p class="home-spark__task">
          {{- if eq $langKey "en" -}}
          No spark today — check back tomorrow.
          {{- else -}}
          今天还没有小火花，明天再来看吧。
          {{- end -}}
        </p>
      </section>
    {{- end -}}

    <section class="spark-checkin" aria-label="{{ $checkinLabel }}">
      <h3 class="spark-checkin__heading">{{ $checkinLabel }}</h3>
      {{- $dateForComments := "" -}}
      {{- if $sparkOK -}}
        {{- $dateForComments = $spark.date -}}
      {{- else -}}
        {{- $dateForComments = now.Format "2006-01-02" -}}
      {{- end -}}
      {{- partial "spark_comments.html" (dict "page" . "date" $dateForComments) -}}
    </section>
  </div>

  <aside class="home-side" aria-label="sidebar">
    <section class="home-side__card" aria-label="{{ $recentLabel }}">
      <h3 class="home-side__heading">{{ $recentLabel }}</h3>
      {{- $posts := where site.RegularPages "Type" "in" site.Params.mainSections -}}
      {{- range first 5 $posts -}}
      <a class="home-side__link" href="{{ .Permalink }}">
        <span class="home-side__title">{{ .Title }}</span>
        <time class="home-side__date" datetime="{{ .Date }}">{{ .Date.Format site.Params.DateFormat }}</time>
      </a>
      {{- end -}}
    </section>

    <section class="home-side__card home-side__social" aria-label="social">
      {{- partial "social_icons.html" (dict "align" "start") -}}
    </section>
  </aside>
</div>
{{- end -}}

/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * a slightly narrower reading width for CJK content, and the home-page
 * two-column layout (Daily Spark hero + sidebar).
 * --------------------------------------------------------------------------- */

/* --- Brand color (Cranberry red) --------------------------------------------
 * Light mode:  #db5079  (cranberry pink)
 * Dark mode:   #ef7fa4  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #db5079;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #ef7fa4;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Home page: two-column layout ------------------------------------------
 * .home-layout      grid: main column flexible, sidebar ~280px
 * .home-main        Daily Spark hero + check-in comment block
 * .home-side        Recent Posts + social icons
 * On viewports <768px the sidebar collapses below the main column.
 * Uses theme tokens (--gap / --border / --radius / --secondary / --primary)
 * so light/dark mode is handled by PaperMod without extra overrides.
 * ------------------------------------------------------------------------- */
.home-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--gap);
  align-items: start;
}

.home-main {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

.home-side {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

/* --- Home Spark hero card ---------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. Theme tokens only,
 * so the card inherits PaperMod's light/dark palette automatically.
 * ------------------------------------------------------------------------- */
.home-spark {
  padding: 1.4em 1.5em 1.6em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-spark__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1em;
  margin-bottom: 0.9em;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}

.home-spark__tag {
  display: inline-block;
  padding: 0.14em 0.8em;
  border: 1px solid var(--primary);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.78em;
  font-weight: 600;
  line-height: 1.6;
}

.home-spark__date {
  font-variant-numeric: tabular-nums;
}

.home-spark__title {
  margin: 0 0 0.35em;
  font-size: 1.6em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
}

.home-spark__sub {
  margin: 0 0 0.5em;
  font-size: 1.15em;
  font-weight: 600;
  line-height: 1.4;
}

.home-spark__task {
  margin: 0;
  color: var(--secondary);
  font-size: 1em;
  line-height: 1.6;
}

.home-spark--empty .home-spark__title {
  font-size: 1.3em;
}

/* --- Spark check-in block ---------------------------------------------------
 * Sits below the hero. Thin top divider + small heading; the Giscus iframe
 * inherits PaperMod's own responsive figure styling.
 * ------------------------------------------------------------------------- */
.spark-checkin {
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

.spark-checkin__heading {
  margin: 0 0 0.8em;
  font-size: 0.95em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

/* --- Home sidebar ----------------------------------------------------------
 * Compact carded lists. Hover lifts the title color to --primary.
 * ------------------------------------------------------------------------- */
.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
  text-decoration: none;
  color: var(--primary);
  transition: color 0.15s ease;
}

.home-side__link:first-of-type {
  border-top: 0;
  padding-top: 0.2em;
}

.home-side__link:hover,
.home-side__link:focus-visible {
  color: var(--primary);
}

.home-side__title {
  font-size: 0.95em;
  font-weight: 600;
  line-height: 1.4;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.home-side__link:hover .home-side__title,
.home-side__link:focus-visible .home-side__title {
  opacity: 1;
}

.home-side__date {
  color: var(--secondary);
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.home-side__social .social-icons {
  margin: 0;
}

/* --- Responsive collapse ----------------------------------------------------
 * Below 768px the sidebar stacks under the main column.
 * ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .home-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

