+{{- /*
+  Giscus comment thread for the daily spark check-in section.
+  Identical wiring to layouts/_partials/comments.html (article-page comments)
+  except:
+    * data-mapping = "specific"  (each day is its own discussion topic)
+    * data-term    = "spark-{{ .date }}" (one thread per calendar day)
+  Receives dict(page, date). Uses $page := .page for .Lang.
+*/ -}}
+
+{{- $page := .page -}}
+{{- $date := .date -}}
+{{- if and $page.Site.Params.comments.giscus.repoid $page.Site.Params.comments.giscus.categoryid -}}
+<script src="https://giscus.app/client.js"
+        data-repo="{{ $page.Site.Params.comments.giscus.repo }}"
+        data-repo-id="{{ $page.Site.Params.comments.giscus.repoid }}"
+        data-category="{{ $page.Site.Params.comments.giscus.category }}"
+        data-category-id="{{ $page.Site.Params.comments.giscus.categoryid }}"
+        data-mapping="specific"
+        data-term="spark-{{ $date }}"
+        data-strict="0"
+        data-reactions-enabled="{{ if $page.Site.Params.comments.giscus.reactionsenabled }}1{{ else }}0{{ end }}"
+        data-emit-metadata="0"
+        data-input-position="bottom"
+        data-theme="light"
+        data-lang="{{ cond (eq $page.Lang "en") "en" "zh-CN" }}"
+        data-light-theme="{{ $page.Site.Params.comments.giscus.lighttheme }}"
+        data-dark-theme="{{ $page.Site.Params.comments.giscus.darktheme }}"
+        crossorigin="anonymous"
+        async>
+</script>
+
+<script>
+  function setSparkGiscusTheme() {
+    const iframe = document.querySelector('iframe.giscus-frame');
+    if (!iframe) return;
+    const theme = document.documentElement.getAttribute('data-theme') === 'dark'
+      ? '{{ $page.Site.Params.comments.giscus.darktheme }}'
+      : '{{ $page.Site.Params.comments.giscus.lighttheme }}';
+    iframe.contentWindow.postMessage(
+      { giscus: { setConfig: { theme } } },
+      'https://giscus.app'
+    );
+  }
+  document.addEventListener('DOMContentLoaded', () => {
+    const observer = new MutationObserver(setSparkGiscusTheme);
+    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
+    setSparkGiscusTheme();
+  });
+</script>
+{{- end -}}
