.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
