{{- /*
  Site-level home page override.
  Layout:
    .home-layout
      .home-main
        .home-spark     (Daily Spark "quest card" with strip header + body)
        .spark-checkin  (Giscus per-day check-in thread, id="checkin")
      .home-side
        .home-side__card  (Recent Posts, top 5)
        .home-side__card  (social icons)
  Only affects the home page (Hugo resolves home kind → index.html first);
  /posts/, /about/, etc. continue to use themes/PaperMod/layouts/list.html.
*/ -}}

{{- define "main" -}}
{{- $spark := hugo.Data.daily_spark -}}
{{- /*
  $sparkOK requires every nested field the template indexes below:
    .date, .tag, .tag.zh, .tag.en,
    .zh.title, .zh.task, .en.title, .en.task.
  Without these guards a malformed data file produces blank tags or
  panics. We also hide the .spark-checkin section entirely when invalid,
  so the empty hero state doesn't render an orphan Giscus thread.
*/ -}}
{{- $sparkOK := and $spark
    (isset $spark "date")
    (isset $spark "tag")
    (isset $spark "zh") (isset (index $spark "zh") "title") (isset (index $spark "zh") "task")
    (isset $spark "en") (isset (index $spark "en") "title") (isset (index $spark "en") "task")
    (isset (index $spark "tag") "zh") (isset (index $spark "tag") "en") -}}
{{- $langKey := cond (eq .Lang "en") "en" "zh" -}}
{{- $headline := cond (eq $langKey "en") "Daily Spark" "地球Online · 今日隐藏任务" -}}
{{- $checkinLabel := cond (eq $langKey "en") "Check in Today" "今日打卡" -}}
{{- $recentLabel := cond (eq $langKey "en") "Recent Posts" "最近文章" -}}
{{- /* Strip + meta copy is constant per language; compute once so both
       the data and the empty-state branches reuse the same strings. */ -}}
{{- $stripLabel := cond (eq $langKey "en") "EARTH ONLINE · DAILY QUEST" "地球ONLINE · 每日任务" -}}
{{- $diffLabel := cond (eq $langKey "en") "Difficulty" "难度" -}}
{{- $timeLabel := cond (eq $langKey "en") "15-30 min" "约15-30分钟" -}}
{{- $ctaLabel := cond (eq $langKey "en") "Accept Quest ↓" "接取任务 ↓" -}}

<div class="home-layout">
  <div class="home-main">
    {{- if $sparkOK -}}
      {{- $tag := index $spark.tag $langKey -}}
      {{- $titleRaw := index (index $spark $langKey) "title" -}}
      {{- $task := index (index $spark $langKey) "task" -}}
      {{- $dateParsed := time $spark.date -}}

      {{- /* 任务编号：日期去横线取末 4 位（YYYY-MM-DD → MMDD）。
             跨语言/构建结果一致，方便玩家「存档位」感。 */ -}}
      {{- $idRaw := replace $spark.date "-" "" -}}
      {{- $idLast4 := substr $idRaw 4 4 -}}

      {{- /* 难度/XP：FNV32a(date) → 1-3 星 + 10-50 XP。
             同日期跨语言、跨构建出同一个值；星位固定 3 槽（实心+空心填满）。 */ -}}
      {{- $hash := hash.FNV32a $spark.date -}}
      {{- $stars := add (mod $hash 3) 1 -}}
      {{- $xp := add (mod $hash 41) 10 -}}
      {{- $starRow := printf "%s%s" (strings.Repeat $stars "★") (strings.Repeat (sub 3 $stars) "☆") -}}

      {{- /* emoji 按 tag.zh 类别映射；标签文字本身走 $langKey（en 页用 "Life/Learning/..."），
             emoji 统一不变以保持视觉锚点。 */ -}}
      {{- $emojiMap := dict "生活" "🏠" "学习" "📚" "创造" "🎨" "运动" "🏃" -}}
      {{- $emoji := index $emojiMap $spark.tag.zh -}}

      {{- /* zh 用「」包裹标题；en 保持裸标题（英文带引号会很怪）。 */ -}}
      {{- $titleDisplay := cond (eq $langKey "en") $titleRaw (printf "「%s」" $titleRaw) -}}

      <section class="home-spark" aria-label="{{ $headline }}">
        <header class="home-spark__strip">
          <span class="home-spark__strip-brand">{{ $stripLabel }}</span>
          <span class="home-spark__strip-right">
            <time class="home-spark__date" datetime="{{ $spark.date }}">
              {{- if eq $langKey "en" -}}
              {{ $dateParsed.Format "Jan 2" }}
              {{- else -}}
              {{ printf "%d月%d日" $dateParsed.Month $dateParsed.Day }}
              {{- end -}}
            </time>
            <span class="home-spark__id">#{{ $idLast4 }}</span>
          </span>
        </header>
        <div class="home-spark__body">
          <span class="home-spark__badge">
            <span class="home-spark__badge-emoji" aria-hidden="true">{{ $emoji }}</span>
            <span class="home-spark__badge-text">{{ $tag }}</span>
          </span>
          <h2 class="home-spark__title">{{ $titleDisplay }}</h2>
          <p class="home-spark__task">{{ $task }}</p>
          <p class="home-spark__meta">
            <span class="home-spark__meta-item">⚔{{ $diffLabel }} {{ $starRow }}</span>
            <span class="home-spark__meta-item">⏱ {{ $timeLabel }}</span>
            <span class="home-spark__meta-item">🪙 +{{ $xp }} XP</span>
          </p>
          <a class="home-spark__cta" href="#checkin">{{ $ctaLabel }}</a>
        </div>
      </section>
    {{- else -}}
      {{- /* 空态：套用新 strip 结构（仅品牌在左，无日期/编号），正文保留旧文案。 */ -}}
      <section class="home-spark home-spark--empty" aria-label="{{ $headline }}">
        <header class="home-spark__strip">
          <span class="home-spark__strip-brand">{{ $stripLabel }}</span>
        </header>
        <div class="home-spark__body">
          <h2 class="home-spark__title">
            {{- if eq $langKey "en" -}}No quest today{{- else -}}今日任务未刷新{{- end -}}
          </h2>
          <p class="home-spark__task">
            {{- if eq $langKey "en" -}}
            The quest system is taking a day off — check back tomorrow.
            {{- else -}}
            今日任务打盹中，明天再来接单。
            {{- end -}}
          </p>
        </div>
      </section>
    {{- end -}}

    {{- if $sparkOK -}}
    <section class="spark-checkin" id="checkin" aria-label="{{ $checkinLabel }}">
      <h3 class="spark-checkin__heading">{{ $checkinLabel }}</h3>
      {{- partial "spark_comments.html" (dict "page" . "date" $spark.date) -}}
    </section>
    {{- end -}}
  </div>

  <aside class="home-side" aria-label="{{ cond (eq $langKey "en") "sidebar" "侧栏" }}">
    <section class="home-side__card" aria-label="{{ $recentLabel }}">
      <h3 class="home-side__heading">{{ $recentLabel }}</h3>
      {{- $posts := where site.RegularPages "Type" "in" site.Params.mainSections -}}
      {{- range first 5 $posts -}}
      <a class="home-side__link" href="{{ .Permalink }}">
        <span class="home-side__title">{{ .Title }}</span>
        <time class="home-side__date" datetime="{{ .Date.Format "2006-01-02" }}">{{ .Date.Format site.Params.DateFormat }}</time>
      </a>
      {{- end -}}
    </section>

    <section class="home-side__card home-side__social" aria-label="social">
      {{- partial "social_icons.html" (dict "align" "start") -}}
    </section>
  </aside>
</div>
{{- end -}}

/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * a slightly narrower reading width for CJK content, and the home-page
 * two-column layout (Daily Spark hero + sidebar).
 * --------------------------------------------------------------------------- */

/* --- Brand color (靖紫 / Quiet purple) ---------------------------------------
 * Light mode:  #5B5BD6  (quiet purple)
 * Dark mode:   #9B9BF5  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #5B5BD6;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #9B9BF5;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Home page: two-column layout ------------------------------------------
 * .home-layout      grid: main column flexible, sidebar ~280px
 * .home-main        Daily Spark hero + check-in comment block
 * .home-side        Recent Posts + social icons
 * On viewports <768px the sidebar collapses below the main column.
 * Uses theme tokens (--gap / --border / --radius / --secondary / --primary)
 * so light/dark mode is handled by PaperMod without extra overrides.
 * ------------------------------------------------------------------------- */
.home-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--gap);
  align-items: start;
}

.home-main {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

.home-side {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
  /* Sticks the sidebar next to the main column while scrolling long posts.
   * top covers PaperMod's fixed header (--header-height, defaults to 60px)
   * plus the grid gap; falls back to a safe value if the theme variable is
   * unavailable or renamed.
   */
  position: sticky;
  top: calc(var(--header-height, 60px) + var(--gap) + 0.5rem);
}

/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. The card is styled
 * like a game-quest ticket: a brand-color strip header ("地球ONLINE · 每日任务"
 * / "EARTH ONLINE · DAILY QUEST") carries the date + task id, then a
 * perforated dashed rule separates it from the body (badge / title /
 * task / meta / accept CTA). Light/dark mode is handled by reading
 * --primary (overridden to brand purple at the top of this file) and
 * --theme / --border / --secondary from PaperMod's theme-vars.css, so
 * no dark-mode selectors are needed for the card itself.
 * ------------------------------------------------------------------------- */

/* Card frame: border + radius, no explicit background (inherits page bg
 * so the strip's brand color is the only saturated block). overflow:hidden
 * clips the strip's top corners to the card's --radius without forcing
 * two more border-radius declarations on the strip itself. The hover lift
 * is a transform + box-shadow + border-color swap, with the transform
 * disabled under prefers-reduced-motion.
 */
.home-spark {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.home-spark:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  border-color: var(--primary);
}

@media (prefers-reduced-motion: reduce) {
  .home-spark:hover {
    transform: none;
  }
}

/* Strip header: solid brand color background, white-in-light / dark-in-dark
 * text via var(--theme) so dark mode auto-flips without an override. The
 * dashed border-bottom is the "ticket perforation" separating header
 * from body — visible on the saturated strip in both color modes.
 */
.home-spark__strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4em 1em;
  padding: 0.7em 1.2em;
  background: var(--primary);
  color: var(--theme);
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.08em;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.4);
}

.home-spark__strip-brand {
  /* "地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY QUEST" — fixed label
   * so the brand always shows up top, regardless of which quest loads. */
  white-space: normal;
}

/* Right group: localized date + task id (e.g. #0815 from MMDD). tabular-nums
 * keeps the digits aligned so the id feels "machine-stamped".
 */
.home-spark__strip-right {
  display: inline-flex;
  align-items: baseline;
  gap: 0.7em;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
}

.home-spark__id {
  opacity: 0.85;
}

/* Body: var(--gap) padding matches the surrounding grid rhythm; the only
 * colored surface here is the badge (a soft pill in --theme), all other
 * text inherits page foreground.
 */
.home-spark__body {
  padding: var(--gap);
  display: flex;
  flex-direction: column;
  gap: 0.8em;
}

/* Type pill: emoji + label. background: var(--theme) keeps it "clean"
 * (same as page bg) so the border alone provides the pill shape; on dark
 * mode --theme flips to PaperMod's near-black, keeping the outline-only
 * look intact without an explicit override.
 */
.home-spark__badge {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
  padding: 0.18em 0.7em;
  background: var(--theme);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 0.82em;
  font-weight: 600;
  color: var(--secondary);
}

.home-spark__badge-emoji {
  font-size: 1.05em;
  line-height: 1;
}

/* Title: zh gets 「」 quotes via the template, en stays bare. Brand-color
 * text wraps with text-wrap: balance so long Chinese titles don't end on
 * a single orphan character.
 */
.home-spark__title {
  margin: 0;
  font-size: 1.55em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
  text-wrap: balance;
  -webkit-text-wrap: balance;
}

.home-spark__task {
  margin: 0;
  color: var(--secondary);
  font-size: 1.02em;
  line-height: 1.65;
}

/* Meta row: ⚔ difficulty · ⏱ time · 🪙 XP. flex with flex-wrap so on
 * narrow viewports the three items stack instead of overflowing. The
 * ::after adds the " · " separator without needing extra inline spans,
 * and it only fires between siblings — not before the first or after
 * the last.
 */
.home-spark__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  margin: 0;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}

.home-spark__meta-item:not(:last-child)::after {
  content: " · ";
  opacity: 0.5;
  margin: 0 0.1em;
}

/* CTA: pill-shaped outline button. Hover fills with brand color; text
 * uses var(--theme) (white in light, near-black in dark) so dark mode
 * gets dark text on the lighter #9B9BF5 background for AA contrast
 * instead of unreadable white-on-light-purple.
 */
.home-spark__cta {
  align-self: flex-start;
  display: inline-block;
  padding: 0.5em 1.3em;
  margin-top: 0.2em;
  border: 1px solid var(--primary);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.9em;
  font-weight: 600;
  text-decoration: none;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.home-spark__cta:hover {
  background: var(--primary);
  color: var(--theme);
}

.home-spark__cta:focus-visible {
  outline: 2px dashed var(--primary);
  outline-offset: 2px;
}

/* Empty-state card: keeps the new strip frame but trims the right side
 * (no date / no id without a real quest). Title is slightly smaller so
 * it doesn't shout "your daily is missing" any louder than the copy.
 */
.home-spark--empty .home-spark__title {
  font-size: 1.3em;
}

/* --- Spark check-in block ---------------------------------------------------
 * Sits below the hero. Thin top divider + small kicker heading; the
 * Giscus iframe inherits PaperMod's own responsive figure styling.
 * The heading is intentionally a "label" (smaller, wide letter-spacing,
 * uppercase on English pages) to layer visually underneath the hero.
 * ------------------------------------------------------------------------- */
.spark-checkin {
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

.spark-checkin__heading {
  margin: 0 0 0.8em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
}

.spark-checkin__heading:lang(en) {
  text-transform: uppercase;
}

/* --- Home sidebar ----------------------------------------------------------
 * Compact carded lists. Hover lifts the title color to --primary.
 * ------------------------------------------------------------------------- */
.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
  text-decoration: none;
  color: var(--primary);
  transition: color 0.15s ease;
}

.home-side__link:first-of-type {
  border-top: 0;
  padding-top: 0.2em;
}

.home-side__link:hover {
  color: var(--secondary);
}

.home-side__link:focus-visible {
  outline: 2px dashed var(--secondary);
  outline-offset: 2px;
}

.home-side__title {
  font-size: 0.95em;
  font-weight: 600;
  line-height: 1.4;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.home-side__link:hover .home-side__title,
.home-side__link:focus-visible .home-side__title {
  opacity: 1;
}

.home-side__date {
  color: var(--secondary);
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.home-side__social .social-icons {
  margin: 0;
}

/* --- Responsive collapse ----------------------------------------------------
 * Below 768px the sidebar stacks under the main column.
 * sticky is also disabled: a single-column page has nowhere for the
 * sidebar to "stick" relative to, and inherited top offsets would leave
 * a visible gap above the cards. The quest card's strip header and meta
 * row already use flex-wrap; nothing extra is needed there — the items
 * just fall to a second line as the column narrows.
 * ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .home-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .home-side {
    position: static;
  }
}

