edits.oldText:
/* Card frame: border + radius, no explicit background (inherits page bg
 * so the strip's brand color is the only saturated block). overflow:hidden
 * clips the strip's top corners to the card's --radius without forcing
 * two more border-radius declarations on the strip itself. The hover lift
 * is a transform + box-shadow + border-color swap, with the transform
 * disabled under prefers-reduced-motion.
 */
.home-spark {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.home-spark:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  border-color: var(--primary);
}

@media (prefers-reduced-motion: reduce) {
  .home-spark:hover {
    transform: none;
  }
}

edits.newText:
/* Card frame: pixel-art dashed border via border-image. The plain
 * `border: 2px solid transparent` reserves 2px on each side for the
 * border-image to draw into (without it, the dashed pattern would push
 * the strip + body 2px inwards on hover-only and jiggle the layout).
 * border-radius is forced to 0 because border-image and border-radius
 * don't compose — a rounded card would clip the pixel dashes into
 * unreadable corners. The dashed pattern (6px dash + 5px gap) flips
 * to a solid var(--pix) on hover; no transition, no transform, so
 * prefers-reduced-motion doesn't need a special case.
 */
.home-spark {
  border: 2px solid transparent;
  border-image: repeating-linear-gradient(
    90deg,
    var(--pix) 0 6px,
    transparent 6px 11px
  ) 2;
  border-radius: 0;
  overflow: hidden;
}

.home-spark:hover {
  border-image: linear-gradient(var(--pix), var(--pix)) 2;
}

