/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * a slightly narrower reading width for CJK content, and the home-page
 * two-column layout (Daily Spark hero + sidebar).
 * --------------------------------------------------------------------------- */

/* --- Brand color (靖紫 / Quiet purple) ---------------------------------------
 * Light mode:  #5B5BD6  (quiet purple)
 * Dark mode:   #9B9BF5  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #5B5BD6;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #9B9BF5;
}

/* --- Pixel-draw color for the quest card frame ------------------------------
 * --pix shares the brand palette with --primary but stays a distinct token so
 * the pixel border can be retuned (slightly darker/lighter, or per-card hue)
 * without affecting the rest of the site. Light uses the brand purple; dark
 * uses the lighter AA-readable brand purple so the dashed pattern stays
 * visible against PaperMod's near-black card background.
 * ------------------------------------------------------------------------- */
:root {
  --pix: #5B5BD6;
}

:root[data-theme="dark"] {
  --pix: #9B9BF5;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Home page: two-column layout ------------------------------------------
 * .home-layout      grid: main column flexible, sidebar ~280px
 * .home-main        Daily Spark hero + check-in comment block
 * .home-side        Recent Posts + social icons
 * On viewports <768px the sidebar collapses below the main column.
 * Uses theme tokens (--gap / --border / --radius / --secondary / --primary)
 * so light/dark mode is handled by PaperMod without extra overrides.
 * ------------------------------------------------------------------------- */
.home-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--gap);
  align-items: start;
}

.home-main {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

.home-side {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
  /* Sticks the sidebar next to the main column while scrolling long posts.
   * top covers PaperMod's fixed header (--header-height, defaults to 60px)
   * plus the grid gap; falls back to a safe value if the theme variable is
   * unavailable or renamed.
   */
  position: sticky;
  top: calc(var(--header-height, 60px) + var(--gap) + 0.5rem);
}

/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. The card is styled
 * like a game-quest ticket: a brand-color strip header ("地球ONLINE · 每日任务"
 * / "EARTH ONLINE · DAILY QUEST") carries the date + task id, then a
 * perforated dashed rule separates it from the body (badge / title /
 * task / meta / accept CTA). Light/dark mode is handled by reading
 * --primary (overridden to brand purple at the top of this file) and
 * --theme / --border / --secondary from PaperMod's theme-vars.css, so
 * no dark-mode selectors are needed for the card itself.
 * ------------------------------------------------------------------------- */

/* Card frame: pixel-art dashed border via border-image. The plain
 * `border: 2px solid transparent` reserves 2px on each side for the
 * border-image to draw into (without it, the dashed pattern would push
 * the strip + body 2px inwards on hover-only and jiggle the layout).
 * border-radius is forced to 0 because border-image and border-radius
 * don't compose — a rounded card would clip the pixel dashes into
 * unreadable corners. The dashed pattern (6px dash + 5px gap) flips
 * to a solid var(--pix) on hover; no transition, no transform, so
 * prefers-reduced-motion doesn't need a special case.
 */
