/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. The card is styled
 * like a game-quest ticket: a brand-color strip header ("地球ONLINE · 每日任务"
 * / "EARTH ONLINE · DAILY QUEST") carries the date + task id, then a clean
 * body holds the badge / title / task / meta. The whole frame is wrapped
 * in a pixel-art dashed border via border-image — a single dashed language
 * for the whole card, no internal perforation between strip and body.
 * Light/dark mode is handled by reading --primary (overridden to brand
 * purple at the top of this file) and --theme / --secondary from PaperMod's
 * theme-vars.css, so no dark-mode selectors are needed for the card itself.
 * ------------------------------------------------------------------------- */

/* Card frame: pixel-art dashed border via border-image. The plain
 * `border: 2px solid transparent` reserves 2px on each side for the
 * border-image to draw into (without it, the dashed pattern would push
 * the strip + body 2px inwards on hover-only and jiggle the layout).
 * border-radius is forced to 0 because border-image and border-radius
 * don't compose — a rounded card would clip the pixel dashes into
 * unreadable corners. The dashed pattern (6px dash + 5px gap) flips
 * to a solid var(--pix) on hover; no transition, no transform, so
 * prefers-reduced-motion doesn't need a special case.
 */
.home-spark {
  border: 2px solid transparent;
  border-image: repeating-linear-gradient(
    90deg,
    var(--pix) 0 6px,
    transparent 6px 11px
  ) 2;
  border-radius: 0;
  overflow: hidden;
}

.home-spark:hover {
  border-image: linear-gradient(var(--pix), var(--pix)) 2;
}

/* Strip header: solid brand color background, white-in-light / dark-in-dark
 * text via var(--theme) so dark mode auto-flips without an override. Square
 * corners to match the pixel frame; the dashed perforation that used to sit
 * between strip and body is gone — the pixel border on the card itself is
 * the only dashed language now, so two dashed rules on one card would just
 * compete.
 */
.home-spark__strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4em 1em;
  padding: 0.7em 1.2em;
  background: var(--primary);
  color: var(--theme);
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.08em;
  border-radius: 0;
}

.home-spark__strip-brand {
  /* "地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY QUEST" — fixed label
   * so the brand always shows up top, regardless of which quest loads. */
  white-space: normal;
}

/* Right group: localized date + task id (e.g. #0815 from MMDD). tabular-nums
 * keeps the digits aligned so the id feels "machine-stamped".
 */
.home-spark__strip-right {
  display: inline-flex;
