  /* Sticks the sidebar next to the main column while scrolling long posts.
   * top covers PaperMod's fixed header (--header-height, defaults to 60px)
   * plus the grid gap; falls back to a safe value if the theme variable is
   * unavailable or renamed.
   */
  position: sticky;
  top: calc(var(--header-height, 60px) + var(--gap) + 0.5rem);
}

/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. The card is styled
 * like a game-quest ticket: a brand-color strip header ("地球ONLINE · 每日任务"
 * / "EARTH ONLINE · DAILY QUEST") carries the date + task id, then a clean
 * body holds the badge / title / task / meta. The whole frame is wrapped
 * in a pixel-art dashed border via border-image — a single dashed language
 * for the whole card, no internal perforation between strip and body.
 * Light/dark mode is handled by reading --primary (overridden to brand
 * purple at the top of this file) and --theme / --secondary from PaperMod's
 * theme-vars.css, so no dark-mode selectors are needed for the card itself.
 * ------------------------------------------------------------------------- */

/* Card frame: pixel-art dashed border via border-image. The plain
 * `border: 2px solid transparent` reserves 2px on each side for the
 * border-image to draw into (without it, the dashed pattern would push
 * the strip + body 2px inwards on hover-only and jiggle the layout).
 * border-radius is forced to 0 because border-image and border-radius
 * don't compose — a rounded card would clip the pixel dashes into
 * unreadable corners. The dashed pattern (6px dash + 5px gap) flips
 * to a solid var(--pix) on hover; no transition, no transform, so
 * prefers-reduced-motion doesn't need a special case.
 */
.home-spark {
  border: 2px solid transparent;
  border-image: repeating-linear-gradient(
    90deg,
    var(--pix) 0 6px,
    transparent 6px 11px
  ) 2;
  border-radius: 0;
  overflow: hidden;
}

.home-spark:hover {
  border-image: linear-gradient(var(--pix), var(--pix)) 2;
}

/* Strip header: solid brand color background, white-in-light / dark-in-dark
 * text via var(--theme) so dark mode auto-flips without an override. Square
 * corners to match the pixel frame; the dashed perforation that used to sit
 * between strip and body is gone — the pixel border on the card itself is
 * the only dashed language now, so two dashed rules on one card would just
 * compete.
 */
.home-spark__strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4em 1em;
  padding: 0.7em 1.2em;
  background: var(--primary);
  color: var(--theme);
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.08em;
  border-radius: 0;
}

.home-spark__strip-brand {
  /* "地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY QUEST" — fixed label
   * so the brand always shows up top, regardless of which quest loads. */
  white-space: normal;
}

/* Right group: localized date + task id (e.g. #0815 from MMDD). tabular-nums
 * keeps the digits aligned so the id feels "machine-stamped".
 */
.home-spark__strip-right {
  display: inline-flex;
  align-items: baseline;
  gap: 0.7em;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
}

.home-spark__id {
  opacity: 0.85;
}

/* Body: var(--gap) padding matches the surrounding grid rhythm; the only
 * colored surface here is the brand-color badge chip, all other text
 * inherits page foreground.
 */
.home-spark__body {
  padding: var(--gap);
  display: flex;
  flex-direction: column;
  gap: 0.8em;
}

/* Type chip: text-only label, no background fill. The brand-color 1px
 * border plus the card's pixel frame form a coherent two-tier outline;
 * text color picks --primary (brand purple) so the chip reads as "tagged
 * with the brand", not as a generic grey label. Square corners to match
 * the rest of the card.
 */
.home-spark__badge {
  align-self: flex-start;
  display: inline-block;
  padding: 0.12em 0.55em;
  border: 1px solid var(--pix);
  border-radius: 0;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--primary);
}

/* Title: zh gets 「」 quotes via the template, en stays bare. Brand-color
 * text wraps with text-wrap: balance so long Chinese titles don't end on
 * a single orphan character.
 */
.home-spark__title {
  margin: 0;
  font-size: 1.55em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
  text-wrap: balance;
  -webkit-text-wrap: balance;

[135 more lines in file. Use offset=215 to continue.]

}

.home-spark__task {
  margin: 0;
  color: var(--secondary);
  font-size: 1.02em;
  line-height: 1.65;
}

/* Meta row: a single inline line ("约15-30分钟" / "15-30 min"). Plain
 * inline flow is enough — no flex, no separator ::after, no wrapper.
 */
.home-spark__meta {
  margin: 0;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}

/* Empty-state card: keeps the strip frame but trims the right side
 * (no date / no id without a real quest). Title is slightly smaller so
 * it doesn't shout "your daily is missing" any louder than the copy.
 * Pixel border + square corners come from the shared .home-spark rules
 * above — this class only tweaks the title size.
 */
.home-spark--empty .home-spark__title {
  font-size: 1.3em;
}

/* --- Spark check-in block ---------------------------------------------------
 * Sits below the hero. Thin top divider + small kicker heading; the
 * Giscus iframe inherits PaperMod's own responsive figure styling.
 * The heading is intentionally a "label" (smaller, wide letter-spacing,
 * uppercase on English pages) to layer visually underneath the hero.
 * ------------------------------------------------------------------------- */
.spark-checkin {
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

.spark-checkin__heading {
  margin: 0 0 0.8em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
}

.spark-checkin__heading:lang(en) {
  text-transform: uppercase;
}

/* --- Home sidebar ----------------------------------------------------------
 * Compact carded lists. Hover lifts the title color to --primary.
 * ------------------------------------------------------------------------- */
.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
  text-decoration: none;
  color: var(--primary);
  transition: color 0.15s ease;
}

.home-side__link:first-of-type {
  border-top: 0;
  padding-top: 0.2em;
}

.home-side__link:hover {
  color: var(--secondary);
}

.home-side__link:focus-visible {
  outline: 2px dashed var(--secondary);
  outline-offset: 2px;
}

.home-side__title {
  font-size: 0.95em;
  font-weight: 600;
  line-height: 1.4;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.home-side__link:hover .home-side__title,
.home-side__link:focus-visible .home-side__title {
  opacity: 1;
}

.home-side__date {
  color: var(--secondary);
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.home-side__social .social-icons {
  margin: 0;
}

/* --- Responsive collapse ----------------------------------------------------
 * Below 768px the sidebar stacks under the main column.
 * sticky is also disabled: a single-column page has nowhere for the
 * sidebar to "stick" relative to, and inherited top offsets would leave
 * a visible gap above the cards. The quest card's strip header and meta
 * row already use flex-wrap; nothing extra is needed there — the items
 * just fall to a second line as the column narrows.
 * ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .home-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .home-side {
    position: static;
  }
}

