/* --- Quests page -------------------------------------------------------------
 * /quests/ 往期任务存档. 月份标题小字 + 1px --border 分割线; 条目用 --border
 * 底边线分隔; tag 徽章复用 .home-spark__kicker 的靖紫色块 (亮 14% / 暗 18%);
 * hover 条目背景极淡靖紫 (与首页卡一致 亮 4% / 暗 6%). 一律走 theme 变量,
 * 不写死背景色, 暗色自适应.
 * ------------------------------------------------------------------------- */
.quests__title {
  margin: 0 0 0.4em;
  font-size: 2em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
}

.quests__desc,
.quests__empty {
  margin: 0 0 1.2em;
  color: var(--secondary);
  font-size: 0.95em;
  line-height: 1.6;
}

.quests__month {
  margin: 0 0 var(--gap);
}

.quests__month-title {
  margin: 1.4em 0 0.5em;
  padding-bottom: 0.4em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
  border-bottom: 1px solid var(--border);
}

.quests__month-title:lang(en) {
  text-transform: uppercase;
}

.quests__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.quests__item {
  padding: 0.9em 0.4em;
  border-bottom: 1px solid var(--border);
  transition: background-color 0.15s ease;
}

.quests__item:last-child {
  border-bottom: 0;
}

.quests__item:hover {
  background: rgba(91, 91, 214, 0.04);
}

[data-theme="dark"] .quests__item:hover {
  background: rgba(155, 155, 245, 0.06);
}

.quests__meta {
  display: flex;
  align-items: center;
  gap: 0.6em;
  margin: 0 0 0.35em;
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
  color: var(--secondary);
}

.quests__tag {
  display: inline-block;
  padding: 0.1em 0.55em;
  border-radius: 4px;
  background: rgba(91, 91, 214, 0.14);
  color: #5B5BD6;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
}

[data-theme="dark"] .quests__tag {
  background: rgba(155, 155, 245, 0.18);
  color: #9B9BF5;
}

.quests__item-title {
  margin: 0 0 0.3em;
  font-size: 1.1em;
  font-weight: 700;
  line-height: 1.35;
  color: var(--primary);
}

.quests__task {
  margin: 0 0 0.45em;
  color: var(--secondary);
  font-size: 0.95em;
  line-height: 1.6;
}

.quests__discussion {
  font-size: 0.82em;
  color: var(--primary);
  text-decoration: none;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.quests__discussion:hover,
.quests__discussion:focus-visible {
  opacity: 1;
}

