/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * a slightly narrower reading width for CJK content, and the home-page
 * two-column layout (Daily Spark hero + sidebar).
 * --------------------------------------------------------------------------- */

/* --- Brand color (靖紫 / Quiet purple) ---------------------------------------
 * Light mode:  #5B5BD6  (quiet purple)
 * Dark mode:   #9B9BF5  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #5B5BD6;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #9B9BF5;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Home page: two-column layout ------------------------------------------
 * .home-layout      grid: main column flexible, sidebar ~280px
 * .home-main        Daily Spark hero + check-in comment block
 * .home-side        Recent Posts + social icons
 * On viewports <768px the sidebar collapses below the main column.
 * Uses theme tokens (--gap / --border / --radius / --secondary / --primary)
 * so light/dark mode is handled by PaperMod without extra overrides.
 * ------------------------------------------------------------------------- */
.home-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--gap);
  align-items: start;
}

.home-main {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

.home-side {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
  /* Sticks the sidebar next to the main column while scrolling long posts.
   * top covers PaperMod's fixed header (--header-height, defaults to 60px)
   * plus the grid gap; falls back to a safe value if the theme variable is
   * unavailable or renamed.
   */
  position: sticky;
  top: calc(var(--header-height, 60px) + var(--gap) + 0.5rem);
}

/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. A clean, modern card:
 * a thin secondary-color label row at the top (brand + localized date +
 * #MMDD id), a 1px border separator, then a kicker / title / task / meta
 * body. Rounded corners (var(--radius)), 1px var(--border) frame,
 * var(--theme) background. On hover the border tints to --primary and the
 * background nudges toward a barely-there indigo (4% / 6% alpha in light /
 * dark mode) — the entire affordance is restrained color, no motion.
 * border-color / background-color transition at 0.25s ease. Light/dark
 * handled by reading --primary / --secondary / --border / --theme / --radius
 * from PaperMod's theme-vars.css; the hover background needs an explicit
 * rgba pair because the tint should not be derived from --theme (which
 * is white in light / dark gray in dark, two very different bases).
 * ------------------------------------------------------------------------- */

/* Card frame: rounded, 1px outline, themed background. overflow: hidden
 * keeps the strip's border-bottom flush with the rounded corners (a child
 * element's border would otherwise extend past the parent's radius).
 * transition covers the hover color shifts only — no transform / motion
 * is involved, so prefers-reduced-motion is a non-issue here.
 */
.home-spark {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--theme);
  transition: border-color 0.25s ease, background-color 0.25s ease;
}

/* Hover tint: border shifts to brand purple; background picks up a
 * barely-there indigo so the card "lifts" subtly without becoming loud.
 * Kept extremely restrained (4% alpha light / 6% alpha dark) — at this
 * density it's a tone-on-tone warmth, not a fill.
 */
.home-spark:hover {
  border-color: var(--primary);
  background: rgba(91, 91, 214, 0.04);
}

[data-theme="dark"] .home-spark:hover {
  background: rgba(155, 155, 245, 0.06);
}

/* Strip header: a plain typography row, not a solid brand bar. Brand
 * label on the left ("地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY
 * QUEST", uppercased on English pages), localized date + #MMDD id on
 * the right. A 1px border-bottom separates it from the body; the card's
 * overflow: hidden keeps that line flush with the rounded corners.
 */
.home-spark__strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4em 1em;
  padding: 0.85em 1.2em;
  font-size: 0.75em;
  letter-spacing: 0.08em;
  color: var(--secondary);
  border-bottom: 1px solid var(--border);
}

.home-spark__strip-brand {
  /* "地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY QUEST" — fixed label
   * so the brand always shows up top, regardless of which quest loads. */
  white-space: normal;
}

.home-spark__strip-brand:lang(en) {
  text-transform: uppercase;
}

/* Right group: localized date + task id (e.g. #0815 from MMDD). tabular-nums
 * keeps the digits aligned so the id feels "machine-stamped".
 */
.home-spark__strip-right {
  display: inline-flex;
  align-items: baseline;
  gap: 0.7em;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
}

/* Body: var(--gap) padding matches the surrounding grid rhythm. Explicit
 * margins (no flex gap) so the kicker sits close to the title, the title
 * + task + meta share a comfortable rhythm, and the spec's "small
 * margin-bottom" on the kicker lands as written.
 */
.home-spark__body {
  padding: var(--gap);
}

/* Kicker: the tag (e.g. "创造" / "Creating") becomes a small brand-purple
 * badge above the title — a translucent chip with rounded corners, not
 * an outlined pill. Light / dark each get an explicit rgba so the tint
 * reads on both backgrounds (a single --primary mix wouldn't, because
 * the chip sits on --theme which is white in light, dark gray in dark).
 * Colors are hard-coded to the brand swatches for the same reason.
 */
.home-spark__kicker {
  display: inline-block;
  margin: 0 0 0.35em;
  padding: 0.15em 0.6em;
  border-radius: 4px;
  background: rgba(91, 91, 214, 0.14);
  color: #5B5BD6;
  font-size: 0.8em;
  font-weight: 600;
  letter-spacing: 0.05em;
}

[data-theme="dark"] .home-spark__kicker {
  background: rgba(155, 155, 245, 0.18);
  color: #9B9BF5;
}

/* Title: zh gets 「」 quotes via the template, en stays bare. Brand-color
 * text wraps with text-wrap: balance so long Chinese titles don't end on
 * a single orphan character.
 */
.home-spark__title {
  margin: 0 0 0.5em;
  font-size: 1.55em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
  text-wrap: balance;
  -webkit-text-wrap: balance;
}

.home-spark__task {
  margin: 0 0 0.5em;
  color: var(--secondary);
  font-size: 1.02em;
  line-height: 1.65;
}

/* Meta row: a single inline line ("约15-30分钟" / "15-30 min"). Plain
 * inline flow is enough — no flex, no separator ::after, no wrapper.
 */
.home-spark__meta {
  margin: 0;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}

/* Empty-state card: keeps the strip frame but trims the right side
 * (no date / no id without a real quest). Title is slightly smaller so
 * it doesn't shout "your daily is missing" any louder than the copy.
 * Rounded frame + themed background come from the shared .home-spark
 * rules above — this class only tweaks the title size.
 */
.home-spark--empty .home-spark__title {
  font-size: 1.3em;
}

.home-spark--empty .home-spark__task {
  /* No __meta follows in the empty state, so the shared 0.5em margin-bottom
   * would leave an off-rhythm gap at the bottom of the card. Collapse it
   * so the body's padding-bottom is the only spacing below the task. */
  margin-bottom: 0;
}

/* --- Spark check-in block ---------------------------------------------------
 * Sits below the hero. Thin top divider + small kicker heading; the
 * Giscus iframe inherits PaperMod's own responsive figure styling.
 * The heading is intentionally a "label" (smaller, wide letter-spacing,
 * uppercase on English pages) to layer visually underneath the hero.
 * ------------------------------------------------------------------------- */
.spark-checkin {
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

.spark-checkin__heading {
  margin: 0 0 0.8em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
}

.spark-checkin__heading:lang(en) {
  text-transform: uppercase;
}

/* --- Home sidebar ----------------------------------------------------------
 * Compact carded lists. Hover lifts the title color to --primary.
 * ------------------------------------------------------------------------- */
.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
  text-decoration: none;
  color: var(--primary);
  transition: color 0.15s ease;
}

.home-side__link:first-of-type {
  border-top: 0;
  padding-top: 0.2em;
}

.home-side__link:hover {
  color: var(--secondary);
}

.home-side__link:focus-visible {
  outline: 2px dashed var(--secondary);
  outline-offset: 2px;
}

.home-side__title {
  font-size: 0.95em;
  font-weight: 600;
  line-height: 1.4;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.home-side__link:hover .home-side__title,
.home-side__link:focus-visible .home-side__title {
  opacity: 1;
}

.home-side__date {
  color: var(--secondary);
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.home-side__social .social-icons {
  margin: 0;
}

/* --- Responsive collapse ----------------------------------------------------
 * Below 768px the sidebar stacks under the main column.
 * sticky is also disabled: a single-column page has nowhere for the
 * sidebar to "stick" relative to, and inherited top offsets would leave
 * a visible gap above the cards. The quest card's strip header and meta
 * row already use flex-wrap; nothing extra is needed there — the items
 * just fall to a second line as the column narrows.
 * ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .home-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .home-side {
    position: static;
  }
}

/* --- Quests page -------------------------------------------------------------
 * /quests/ 往期任务存档. 月份标题小字 + 1px --border 分割线; 条目用 --border
 * 底边线分隔; tag 徽章复用 .home-spark__kicker 的靖紫色块 (亮 14% / 暗 18%);
 * 条目行不加 hover 背景 — 整行不可点, 只有「打卡讨论」链接可点, 整行变色
 * 会误导. 一律走 theme 变量, 不写死背景色, 暗色自适应.
 * ------------------------------------------------------------------------- */
.quests__title {
  margin: 0 0 0.4em;
  font-size: 2em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
}

