{{- /*
  Site-level home page override.
  Layout:
    .home-layout
      .home-main
        .home-spark     (Daily Spark "quest card" with strip header + body)
        .spark-checkin  (Giscus per-day check-in thread)
      .home-side
        .home-side__card  (Past Quests, top 7 from site.Data.daily_spark_history
                           minus today's date; whole card omitted if empty)
        .home-side__card  (social icons)
  Only affects the home page (Hugo resolves home kind → index.html first);
  /posts/, /about/, etc. continue to use themes/PaperMod/layouts/list.html.
*/ -}}

{{- define "main" -}}
{{- $spark := hugo.Data.daily_spark -}}
{{- /*
  $sparkOK requires every nested field the template indexes below:
    .date, .tag, .tag.zh, .tag.en,
    .zh.title, .zh.task, .en.title, .en.task.
  Without these guards a malformed data file produces blank tags or
  panics. We also hide the .spark-checkin section entirely when invalid,
  so the empty hero state doesn't render an orphan Giscus thread.
*/ -}}
{{- $sparkOK := and $spark
    (isset $spark "date")
    (isset $spark "tag")
    (isset $spark "zh") (isset (index $spark "zh") "title") (isset (index $spark "zh") "task")
    (isset $spark "en") (isset (index $spark "en") "title") (isset (index $spark "en") "task")
    (isset (index $spark "tag") "zh") (isset (index $spark "tag") "en") -}}
{{- $langKey := cond (eq .Lang "en") "en" "zh" -}}
{{- $headline := cond (eq $langKey "en") "Daily Spark" "地球Online · 今日隐藏任务" -}}
{{- $checkinLabel := cond (eq $langKey "en") "Check in Today" "今日打卡" -}}
{{- $pastLabel := cond (eq $langKey "en") "Past Quests" "往期任务" -}}
{{- $pastMoreLabel := cond (eq $langKey "en") "All →" "查看全部 →" -}}
{{- /* Strip + meta copy is constant per language; compute once so both
       the data and the empty-state branches reuse the same strings. */ -}}
{{- $stripLabel := cond (eq $langKey "en") "EARTH ONLINE · DAILY QUEST" "地球ONLINE · 每日任务" -}}
{{- $timeLabel := cond (eq $langKey "en") "15-30 min" "约15-30分钟" -}}

<div class="home-layout">
  <div class="home-main">
    {{- if $sparkOK -}}
      {{- $tag := index $spark.tag $langKey -}}
      {{- $titleRaw := index (index $spark $langKey) "title" -}}
      {{- $task := index (index $spark $langKey) "task" -}}
      {{- $dateParsed := time $spark.date -}}

      {{- /* 任务编号：日期去横线取末 4 位（YYYY-MM-DD → MMDD）。
             跨语言/构建结果一致，方便玩家「存档位」感。 */ -}}
      {{- $idRaw := replace $spark.date "-" "" -}}
      {{- $idLast4 := substr $idRaw 4 4 -}}

      {{- /* zh 用「」包裹标题；en 保持裸标题（英文带引号会很怪）。 */ -}}
      {{- $titleDisplay := cond (eq $langKey "en") $titleRaw (printf "「%s」" $titleRaw) -}}

      <section class="home-spark" aria-label="{{ $headline }}">
        <header class="home-spark__strip">
          <span class="home-spark__strip-brand">{{ $stripLabel }}</span>
          <span class="home-spark__strip-right">
            <time class="home-spark__date" datetime="{{ $spark.date }}">
              {{- if eq $langKey "en" -}}
              {{ $dateParsed.Format "Jan 2" }}
              {{- else -}}
              {{ printf "%d月%d日" $dateParsed.Month $dateParsed.Day }}
              {{- end -}}
            </time>
            <span class="home-spark__id">#{{ $idLast4 }}</span>
          </span>
        </header>
        <div class="home-spark__body">
          <p class="home-spark__kicker">{{ $tag }}</p>
          <h2 class="home-spark__title">{{ $titleDisplay }}</h2>
          <p class="home-spark__task">{{ $task }}</p>
          <p class="home-spark__meta">{{ $timeLabel }}</p>
        </div>
      </section>
    {{- else -}}
      {{- /* 空态：套用新 strip 结构（仅品牌在左，无日期/编号），正文保留旧文案。 */ -}}
      <section class="home-spark home-spark--empty" aria-label="{{ $headline }}">
        <header class="home-spark__strip">
          <span class="home-spark__strip-brand">{{ $stripLabel }}</span>
        </header>
        <div class="home-spark__body">
          <h2 class="home-spark__title">
            {{- if eq $langKey "en" -}}No quest today{{- else -}}今日任务未刷新{{- end -}}
          </h2>
          <p class="home-spark__task">
            {{- if eq $langKey "en" -}}
            The quest system is taking a day off — check back tomorrow.
            {{- else -}}
            今日任务打盹中，明天再来接单。
            {{- end -}}
          </p>
        </div>
      </section>
    {{- end -}}

    {{- if $sparkOK -}}
    <section class="spark-checkin" aria-label="{{ $checkinLabel }}">
      <h3 class="spark-checkin__heading">{{ $checkinLabel }}</h3>
      {{- partial "spark_comments.html" (dict "page" . "date" $spark.date) -}}
    </section>
    {{- end -}}
  </div>

  <aside class="home-side" aria-label="{{ cond (eq $langKey "en") "sidebar" "侧栏" }}">
    {{- /*
      Sidebar Past Quests card (replaces the previous Recent Posts card).
      Source: site.Data.daily_spark_history, minus the main-card date so
      it doesn't double up, desc-sorted, top 7. Same pre-filter shape as
      layouts/quests.html (zh/en title required for current language),
      kept minimal because we only read title + date here, not tag/task.
      When the filtered list is empty the entire card is omitted (the
      sidebar collapses down to just the social-icons card).
    */ -}}
    {{- $today := "" -}}
    {{- if $sparkOK -}}{{- $today = $spark.date -}}{{- end -}}
    {{- $pastList := slice -}}
    {{- $history := hugo.Data.daily_spark_history -}}
    {{- if $history -}}
      {{- range $history -}}
        {{- $pastOK := and (not (eq .date $today))
                          (isset . "tag") (isset (index . "tag") $langKey)
                          (isset . $langKey)
                          (isset (index . $langKey) "title") -}}
        {{- if $pastOK -}}
          {{- $pastList = $pastList | append . -}}
        {{- end -}}
      {{- end -}}
    {{- end -}}
    {{- $pastTop := first 7 (sort $pastList "date" "desc") -}}
    {{- if gt (len $pastTop) 0 -}}
    <section class="home-side__card" aria-label="{{ $pastLabel }}">
      <div class="home-side__heading-row">
        <h3 class="home-side__heading">{{ $pastLabel }}</h3>
        <a class="home-side__more" href="{{ relLangURL `/quests/` }}">{{ $pastMoreLabel }}</a>
      </div>
      {{- range $pastTop -}}
        {{- $dateParsed := time .date -}}
        {{- $dateDisplay := cond (eq $langKey "en")
            ($dateParsed.Format "Jan 2")
            (printf "%d月%d日" $dateParsed.Month $dateParsed.Day) -}}
        {{- $questURL := relLangURL (printf `/quests/#spark-%s` .date) -}}
      <a class="home-side__link" href="{{ $questURL }}">
        <span class="home-side__title">{{ index (index . $langKey) "title" }}</span>
        <time class="home-side__date" datetime="{{ .date }}">{{ $dateDisplay }}</time>
      </a>
      {{- end -}}
    </section>
    {{- end -}}

    <section class="home-side__card home-side__social" aria-label="social">
      {{- partial "social_icons.html" (dict "align" "start") -}}
    </section>
  </aside>
</div>
{{- end -}}

{{- /*
  Giscus comment thread for the home-page daily spark check-in section.
  Mirrors layouts/_partials/comments.html (used by article single pages) but
  adapted for the home-page context, which has no implicit .Date and no
  implicit .Permalink:

    * Caller passes (dict "page" . "date" $spark.date); we bind those to
      $page and $date up front instead of relying on the current page.
    * data-mapping is hard-coded to "specific" so each calendar day maps to
      its own discussion topic rather than sharing the article-path thread.
    * data-term is hard-coded to "spark-{{ $date }}" (e.g. "spark-2026-08-15"),
      giving one stable thread id per day across zh/en rebuilds.
    * The theme-switching JS is renamed to setSparkGiscusTheme so it never
      collides with setGiscusTheme from comments.html if both partials are
      ever rendered on the same page in the future.
*/ -}}

{{- $page := .page -}}
{{- $date := .date -}}
{{- if and $page.Site.Params.comments.giscus.repoid $page.Site.Params.comments.giscus.categoryid -}}
<script src="https://giscus.app/client.js"
        data-repo="{{ $page.Site.Params.comments.giscus.repo }}"
        data-repo-id="{{ $page.Site.Params.comments.giscus.repoid }}"
        data-category="{{ $page.Site.Params.comments.spark.category }}"
        data-category-id="{{ $page.Site.Params.comments.spark.categoryid }}"
        data-mapping="specific"
        data-term="spark-{{ $date }}"
        data-strict="0"
        data-reactions-enabled="{{ if $page.Site.Params.comments.giscus.reactionsenabled }}1{{ else }}0{{ end }}"
        data-emit-metadata="0"
        data-input-position="bottom"
        data-theme="light"
        data-lang="{{ cond (eq $page.Lang "en") "en" "zh-CN" }}"
        data-light-theme="{{ $page.Site.Params.comments.giscus.lighttheme }}"
        data-dark-theme="{{ $page.Site.Params.comments.giscus.darktheme }}"
        crossorigin="anonymous"
        async>
</script>

<script>
  function setSparkGiscusTheme() {
    const iframe = document.querySelector('iframe.giscus-frame');
    if (!iframe) return;
    const theme = document.documentElement.getAttribute('data-theme') === 'dark'
      ? '{{ $page.Site.Params.comments.giscus.darktheme }}'
      : '{{ $page.Site.Params.comments.giscus.lighttheme }}';
    iframe.contentWindow.postMessage(
      { giscus: { setConfig: { theme } } },
      'https://giscus.app'
    );
  }
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new MutationObserver(setSparkGiscusTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    setSparkGiscusTheme();
  });
</script>

{{- /* Giscus fallback link: a small, secondary-coloured line under the
       embedded thread that lets readers jump to the GitHub Discussions
       search for `spark-<date>` — useful when giscus is blocked, when
       someone wants to attach images, or when reading prefers a real
       forum thread. Same route shape as .quests__discussion in
       layouts/quests.html (the search URL never 404s regardless of whether
       a discussion exists; giscus is lazy-create so no nodes are wasted
       when nobody uses this fallback). Opens in a new tab. */ -}}
<p class="spark-checkin__ghlink">
  <a href="https://github.com/sanbika/sanbika.github.io/discussions?discussions_q=spark-{{ $date }}" target="_blank" rel="noopener noreferrer">
    {{- if eq $page.Lang "en" -}}
    Comment on GitHub · images supported ↗
    {{- else -}}
    在 GitHub 上评论 · 可传图 ↗
    {{- end -}}
  </a>
</p>
{{- end -}}

/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * a slightly narrower reading width for CJK content, and the home-page
 * two-column layout (Daily Spark hero + sidebar).
 * --------------------------------------------------------------------------- */

/* --- Brand color (靖紫 / Quiet purple) ---------------------------------------
 * Light mode:  #5B5BD6  (quiet purple)
 * Dark mode:   #9B9BF5  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #5B5BD6;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #9B9BF5;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Home page: two-column layout ------------------------------------------
 * .home-layout      grid: main column flexible, sidebar ~280px
 * .home-main        Daily Spark hero + check-in comment block
 * .home-side        Recent Posts + social icons
 * On viewports <768px the sidebar collapses below the main column.
 * Uses theme tokens (--gap / --border / --radius / --secondary / --primary)
 * so light/dark mode is handled by PaperMod without extra overrides.
 * ------------------------------------------------------------------------- */
.home-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--gap);
  align-items: start;
}

.home-main {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
}

.home-side {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-width: 0;
  /* Sticks the sidebar next to the main column while scrolling long posts.
   * top covers PaperMod's fixed header (--header-height, defaults to 60px)
   * plus the grid gap; falls back to a safe value if the theme variable is
   * unavailable or renamed.
   */
  position: sticky;
  top: calc(var(--header-height, 60px) + var(--gap) + 0.5rem);
}

/* --- Home Spark "quest card" ------------------------------------------------
 * Reads site.Data.daily_spark via layouts/index.html. A clean, modern card:
 * a thin secondary-color label row at the top (brand + localized date +
 * #MMDD id), a 1px border separator, then a kicker / title / task / meta
 * body. Rounded corners (var(--radius)), 1px var(--border) frame,
 * var(--theme) background. On hover the border tints to --primary and the
 * background nudges toward a barely-there indigo (4% / 6% alpha in light /
 * dark mode) — the entire affordance is restrained color, no motion.
 * border-color / background-color transition at 0.25s ease. Light/dark
 * handled by reading --primary / --secondary / --border / --theme / --radius
 * from PaperMod's theme-vars.css; the hover background needs an explicit
 * rgba pair because the tint should not be derived from --theme (which
 * is white in light / dark gray in dark, two very different bases).
 * ------------------------------------------------------------------------- */

/* Card frame: rounded, 1px outline, themed background. overflow: hidden
 * keeps the strip's border-bottom flush with the rounded corners (a child
 * element's border would otherwise extend past the parent's radius).
 * transition covers the hover color shifts only — no transform / motion
 * is involved, so prefers-reduced-motion is a non-issue here.
 */
.home-spark {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--theme);
  transition: border-color 0.25s ease, background-color 0.25s ease;
}

/* Hover tint: border shifts to brand purple; background picks up a
 * barely-there indigo so the card "lifts" subtly without becoming loud.
 * Kept extremely restrained (4% alpha light / 6% alpha dark) — at this
 * density it's a tone-on-tone warmth, not a fill.
 */
.home-spark:hover {
  border-color: var(--primary);
  background: rgba(91, 91, 214, 0.04);
}

[data-theme="dark"] .home-spark:hover {
  background: rgba(155, 155, 245, 0.06);
}

/* Strip header: a plain typography row, not a solid brand bar. Brand
 * label on the left ("地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY
 * QUEST", uppercased on English pages), localized date + #MMDD id on
 * the right. A 1px border-bottom separates it from the body; the card's
 * overflow: hidden keeps that line flush with the rounded corners.
 */
.home-spark__strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4em 1em;
  padding: 0.85em 1.2em;
  font-size: 0.75em;
  letter-spacing: 0.08em;
  color: var(--secondary);
  border-bottom: 1px solid var(--border);
}

.home-spark__strip-brand {
  /* "地球ONLINE · 每日任务" / "EARTH ONLINE · DAILY QUEST" — fixed label
   * so the brand always shows up top, regardless of which quest loads. */
  white-space: normal;
}

.home-spark__strip-brand:lang(en) {
  text-transform: uppercase;
}

/* Right group: localized date + task id (e.g. #0815 from MMDD). tabular-nums
 * keeps the digits aligned so the id feels "machine-stamped".
 */
.home-spark__strip-right {
  display: inline-flex;
  align-items: baseline;
  gap: 0.7em;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
}

/* Body: var(--gap) padding matches the surrounding grid rhythm. Explicit
 * margins (no flex gap) so the kicker sits close to the title, the title
 * + task + meta share a comfortable rhythm, and the spec's "small
 * margin-bottom" on the kicker lands as written.
 */
.home-spark__body {
  padding: var(--gap);
}

/* Kicker: the tag (e.g. "创造" / "Creating") becomes a small brand-purple
 * badge above the title — a translucent chip with rounded corners, not
 * an outlined pill. Light / dark each get an explicit rgba so the tint
 * reads on both backgrounds (a single --primary mix wouldn't, because
 * the chip sits on --theme which is white in light, dark gray in dark).
 * Colors are hard-coded to the brand swatches for the same reason.
 */
.home-spark__kicker {
  display: inline-block;
  margin: 0 0 0.35em;
  padding: 0.15em 0.6em;
  border-radius: 4px;
  background: rgba(91, 91, 214, 0.14);
  color: #5B5BD6;
  font-size: 0.8em;
  font-weight: 600;
  letter-spacing: 0.05em;
}

[data-theme="dark"] .home-spark__kicker {
  background: rgba(155, 155, 245, 0.18);
  color: #9B9BF5;
}

/* Title: zh gets 「」 quotes via the template, en stays bare. Brand-color
 * text wraps with text-wrap: balance so long Chinese titles don't end on
 * a single orphan character.
 */
.home-spark__title {
  margin: 0 0 0.5em;
  font-size: 1.55em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
  text-wrap: balance;
  -webkit-text-wrap: balance;
}

.home-spark__task {
  margin: 0 0 0.5em;
  color: var(--secondary);
  font-size: 1.02em;
  line-height: 1.65;
}

/* Meta row: a single inline line ("约15-30分钟" / "15-30 min"). Plain
 * inline flow is enough — no flex, no separator ::after, no wrapper.
 */
.home-spark__meta {
  margin: 0;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}

/* Empty-state card: keeps the strip frame but trims the right side
 * (no date / no id without a real quest). Title is slightly smaller so
 * it doesn't shout "your daily is missing" any louder than the copy.
 * Rounded frame + themed background come from the shared .home-spark
 * rules above — this class only tweaks the title size.
 */
.home-spark--empty .home-spark__title {
  font-size: 1.3em;
}

.home-spark--empty .home-spark__task {
  /* No __meta follows in the empty state, so the shared 0.5em margin-bottom
   * would leave an off-rhythm gap at the bottom of the card. Collapse it
   * so the body's padding-bottom is the only spacing below the task. */
  margin-bottom: 0;
}

/* --- Spark check-in block ---------------------------------------------------
 * Sits below the hero. Thin top divider + small kicker heading; the
 * Giscus iframe inherits PaperMod's own responsive figure styling.
 * The heading is intentionally a "label" (smaller, wide letter-spacing,
 * uppercase on English pages) to layer visually underneath the hero.
 * ------------------------------------------------------------------------- */
.spark-checkin {
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

.spark-checkin__heading {
  margin: 0 0 0.8em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
}

.spark-checkin__heading:lang(en) {
  text-transform: uppercase;
}

/* GitHub fallback link below the Giscus iframe. A small, secondary-color
 * line that mirrors .quests__discussion's visual register so the two
 * surfaces (home spark card + /quests/ entries) read as the same family.
 * Hover lifts to brand color; the arrow ↗ is part of the link text and is
 * wrapped by the colour transition naturally.
 */
.spark-checkin__ghlink {
  margin: 1em 0 0;
  font-size: 0.82em;
  line-height: 1.5;
}

.spark-checkin__ghlink a {
  color: var(--secondary);
  text-decoration: none;
  transition: color 0.15s ease;
}

.spark-checkin__ghlink a:hover,
.spark-checkin__ghlink a:focus-visible {
  color: var(--primary);
}

/* --- Home sidebar ----------------------------------------------------------
 * Compact carded lists. Hover lifts the title color to --primary.
 * ------------------------------------------------------------------------- */
.home-side__card {
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.home-side__heading {
  margin: 0 0 0.6em;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--secondary);
}

/* Heading row used by the Past Quests card: title on the left + small
 * "查看全部 → / All →" link on the right. The row replaces the heading's
 * own margin-bottom so spacing matches the rest of the card surface
 * (.home-side__heading no longer drives spacing when wrapped here).
 */
.home-side__heading-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6em;
  margin: 0 0 0.6em;
}

.home-side__heading-row .home-side__heading {
  margin: 0;
}

.home-side__more {
  font-size: 0.78em;
  color: var(--secondary);
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.15s ease;
}

.home-side__more:hover,
.home-side__more:focus-visible {
  color: var(--primary);
}

.home-side__link {
  display: flex;
  flex-direction: column;
  gap: 0.15em;
  padding: 0.5em 0;
  border-top: 1px dashed var(--border);
  text-decoration: none;
  color: var(--primary);
  transition: color 0.15s ease;
}

.home-side__link:first-of-type {
  border-top: 0;
  padding-top: 0.2em;
}

.home-side__link:hover {
  color: var(--secondary);
}

.home-side__link:focus-visible {
  outline: 2px dashed var(--secondary);
  outline-offset: 2px;
}

.home-side__title {
  font-size: 0.95em;
  font-weight: 600;
  line-height: 1.4;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.home-side__link:hover .home-side__title,
.home-side__link:focus-visible .home-side__title {
  opacity: 1;
}

.home-side__date {
  color: var(--secondary);
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.home-side__social .social-icons {
  margin: 0;
}

/* --- Responsive collapse ----------------------------------------------------
 * Below 768px the sidebar stacks under the main column.
 * sticky is also disabled: a single-column page has nowhere for the
 * sidebar to "stick" relative to, and inherited top offsets would leave
 * a visible gap above the cards. The quest card's strip header and meta
 * row already use flex-wrap; nothing extra is needed there — the items
 * just fall to a second line as the column narrows.
 * ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .home-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .home-side {
    position: static;
  }
}

/* --- Quests page -------------------------------------------------------------
 * /quests/ 往期任务存档. 月份标题小字 + 1px --border 分割线; 条目用 --border
 * 底边线分隔; tag 徽章复用 .home-spark__kicker 的靖紫色块 (亮 14% / 暗 18%);
 * 条目行不加 hover 背景 — 整行不可点, 只有「打卡讨论」链接可点, 整行变色
 * 会误导. 一律走 theme 变量, 不写死背景色, 暗色自适应.
 * ------------------------------------------------------------------------- */
.quests__title {
  margin: 0 0 0.4em;
  font-size: 2em;
  font-weight: 700;
  line-height: 1.3;
  color: var(--primary);
}

.quests__desc,
.quests__empty {
  margin: 0 0 1.2em;
  color: var(--secondary);
  font-size: 0.95em;
  line-height: 1.6;
}

.quests__month {
  margin: 0 0 var(--gap);
}

.quests__month-title {
  margin: 1.4em 0 0.5em;
  padding-bottom: 0.4em;
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--secondary);
  border-bottom: 1px solid var(--border);
}

.quests__month-title:lang(en) {
  text-transform: uppercase;
}

.quests__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.quests__item {
  /* No hover background: the row itself is not clickable, only the inner
   * 打卡讨论 link is. Tinting the whole row on hover would falsely imply
   * the entire item is interactive. The link keeps its own :hover /
   * :focus-visible affordance via .quests__discussion below.
   * transition / background-color pair removed together with the old
   * :hover rule, so no dead styles linger.
   *
   * scroll-margin-top offsets the sticky-header height (~60px) plus a
   * little breathing room when the browser scrolls an anchored item
   * into view (e.g. from the home sidebar's /quests/#spark-<date>
   * links); without it the heading row would slide behind the nav.
   */
  padding: 0.9em 0.4em;
  border-bottom: 1px solid var(--border);
  scroll-margin-top: 70px;
}

.quests__item:last-child {
  border-bottom: 0;
}

.quests__meta {
  display: flex;
  align-items: center;
  gap: 0.6em;
  margin: 0 0 0.35em;
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
  color: var(--secondary);
}

.quests__tag {
  display: inline-block;
  padding: 0.1em 0.55em;
  border-radius: 4px;
  background: rgba(91, 91, 214, 0.14);
  color: #5B5BD6;
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.04em;
}

[data-theme="dark"] .quests__tag {
  background: rgba(155, 155, 245, 0.18);
  color: #9B9BF5;
}

.quests__item-title {
  margin: 0 0 0.3em;
  font-size: 1.1em;
  font-weight: 700;
  line-height: 1.35;
  color: var(--primary);
}

.quests__task {
  margin: 0 0 0.45em;
  color: var(--secondary);
  font-size: 0.95em;
  line-height: 1.6;
}

.quests__discussion {
  font-size: 0.82em;
  color: var(--primary);
  text-decoration: none;
  opacity: 0.85;
  transition: opacity 0.15s ease;
}

.quests__discussion:hover,
.quests__discussion:focus-visible {
  opacity: 1;
}

{{- /*
  往期任务列表页模板 (layouts/quests.html).
  数据源: site.Data.daily_spark_history (数组, 每项 {date, tag, zh, en}, 结构
  与 daily_spark.json 同; 可能为空/缺失/字段不全). 渲染策略:
    1. 先把 $history 预过滤为 $clean: 留下 date 形如 YYYY-MM-DD 且
       tag.zh/tag.en/zh.title/zh.task/en.title/en.task 都存在的条目;
    2. 按 date 倒序 $clean;
    3. 按 YYYY-MM 分组, 月份标题本地化 (2026年8月 / Aug 2026);
    4. 每条显示本地化日期 + tag 徽章 + 标题 (zh 加「」, en 裸) + 任务正文 +
       「打卡讨论」链接: 永远跳到 GitHub Discussions 搜索页
       (?discussions_q=spark-<date>), 该搜索页永不 404, 无讨论则空结果.
  为什么在 sort 之前就做预过滤 (而不是只在渲染时跳过): 月份键是通过
  substr .date 0 7 抽取并用 time() 解析的, Hugo 的 time() 对不可解析
  字符串会直接报错而非返回零值 — 预过滤保证月份键也一定可解析.
  字段守卫的形态与 layouts/index.html 的 $sparkOK 保持一致.
  镜像自 layouts/index.html 的字段读取方式 ($langKey / index 嵌套), 遵循现有
  站点的 site-specific UI 字符串惯例 (cond on .Lang), 不为这一页新增 i18n yaml.
*/ -}}
{{- define "main" -}}
{{- $history := hugo.Data.daily_spark_history -}}
{{- $langKey := cond (eq .Lang "en") "en" "zh" -}}
{{- $checkinText := cond (eq $langKey "en") "Check in ↗" "打卡讨论 ↗" -}}
{{- $emptyText := cond (eq $langKey "en") "No archive yet." "还没有存档。" -}}
{{- /* 日期格式守卫: \d{4}-\d{2}-\d{2} + 月 01-12 + 日 01-31. 形如 "2026-13-01"
     这类能让宽松正则通过但仍会让 time() 崩掉的字符串也一并挡住. 内层渲染
     循环不再重做此项检查, 因为 $clean 已确保 date 可解析. */ -}}
{{- $datePattern := `^(19|20)\d{2}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$` -}}

{{- /* 预过滤: 字段齐全且 date 可解析才进 $clean. sort / 月份键抽取 / time()
       都不再需要兜底守卫. tag.zh/tag.en 与 zh.title/zh.task/en.title/en.task
       全检, 跟 reviewer 的要求一致; 也与 index.html 的 $sparkOK 同形. */ -}}
{{- $clean := slice -}}
{{- if $history -}}
  {{- range $history -}}
    {{- $ok := and (findRE $datePattern .date)
                  (isset . "tag")
                  (isset (index . "tag") "zh")
                  (isset (index . "tag") "en")
                  (isset . "zh") (isset (index . "zh") "title") (isset (index . "zh") "task")
                  (isset . "en") (isset (index . "en") "title") (isset (index . "en") "task") -}}
    {{- if $ok -}}
      {{- $clean = $clean | append . -}}
    {{- end -}}
  {{- end -}}
{{- end -}}

<div class="quests">
  <header class="quests__intro">
    <h1 class="quests__title">{{ .Title }}</h1>
    {{- with .Description -}}
    <p class="quests__desc">{{ . }}</p>
    {{- end -}}
  </header>

  {{- if not $clean -}}
    <p class="quests__empty">{{ $emptyText }}</p>
  {{- else -}}
    {{- /* 倒序: 最新在前. $sorted 既是外层分组遍历源, 也是每组内层的逐条源,
           同一份切片复用可保证每组内仍按 date desc. */ -}}
    {{- $sorted := sort $clean "date" "desc" -}}

    {{- /* 从 $sorted 顺序抽取唯一月份键 (YYYY-MM). 因为 $sorted 已 desc, 月份
           键也天然 desc, 无需再排序. 用 slice + in 而非 dict 是为了让范围输出
           顺序稳定 (Go map 迭代无序). */ -}}
    {{- $months := slice -}}
    {{- range $sorted -}}
      {{- $m := substr .date 0 7 -}}
      {{- if not (in $months $m) -}}
        {{- $months = $months | append $m -}}
      {{- end -}}
    {{- end -}}

    {{- range $months -}}
      {{- $month := . -}}
      {{- $monthTime := time (printf "%s-01" $month) -}}
      {{- $monthTitle := cond (eq $langKey "en")
          ($monthTime.Format "Jan 2006")
          (printf "%d年%d月" $monthTime.Year $monthTime.Month) -}}

      <section class="quests__month">
        <h2 class="quests__month-title">{{ $monthTitle }}</h2>
        <ul class="quests__list">
          {{- range $sorted -}}
            {{- if hasPrefix .date (printf "%s-" $month) -}}
              {{- $dateParsed := time .date -}}
              {{- $tag := index .tag $langKey -}}
              {{- $titleRaw := index (index . $langKey) "title" -}}
              {{- $task := index (index . $langKey) "task" -}}
              {{- $titleDisplay := cond (eq $langKey "en") $titleRaw (printf "「%s」" $titleRaw) -}}
              {{- $dateDisplay := cond (eq $langKey "en")
                  ($dateParsed.Format "Jan 2")
                  (printf "%d月%d日" $dateParsed.Month $dateParsed.Day) -}}
              {{- $discussionURL := printf "https://github.com/sanbika/sanbika.github.io/discussions?discussions_q=spark-%s" .date -}}

              <li class="quests__item" id="spark-{{ .date }}">
                <div class="quests__meta">
                  <time class="quests__date" datetime="{{ .date }}">{{ $dateDisplay }}</time>
                  <span class="quests__tag">{{ $tag }}</span>
                </div>
                <h3 class="quests__item-title">{{ $titleDisplay }}</h3>
                <p class="quests__task">{{ $task }}</p>
                <a class="quests__discussion" href="{{ $discussionURL }}" target="_blank" rel="noopener">{{ $checkinText }}</a>
              </li>
            {{- end -}}
          {{- end -}}
        </ul>
      </section>
    {{- end -}}
  {{- end -}}
</div>
{{- end -}}

[
  {
    "date": "2026-08-15",
    "tag": {
      "zh": "创造",
      "en": "Creating"
    },
    "zh": {
      "title": "水果拼盘大作战",
      "task": "找出家里至少3种当季水果，发挥想象力摆一个有趣的拼盘，拍照留念"
    },
    "en": {
      "title": "Fruit Arrangement Art",
      "task": "Arrange at least 3 seasonal fruits into a creative pattern, snap a photo"
    }
  }
]

