edits.oldText:
/* No hover background: the row itself is not clickable, only the inner
   * 打卡讨论 link is. Tinting the whole row on hover would falsely imply
   * the entire item is interactive. The link keeps its own :hover /
   * :focus-visible affordance via .quests__discussion below.
   * transition / background-color pair removed together with the old
   * :hover rule, so no dead styles linger.
   *
   * scroll-margin-top offsets the sticky-header height (~60px) plus a
   * little breathing room when the browser scrolls an anchored item
   * into view (e.g. from the home sidebar's /quests/#spark-<date>
   * links); without it the heading row would slide behind the nav.
   */
  padding: 0.9em 0.4em;
  border-bottom: 1px solid var(--border);
  scroll-margin-top: 70px;
}

